#!/bin/bash
# Uninstall script for OpenWebStart
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling OpenWebStart..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping OpenWebStart if running..."
pkill -f "OpenWebStart" 2>/dev/null || true

# Remove $HOME/.cache/icedtea-web
echo "Removing $HOME/.cache/icedtea-web..."
if [ -d "$HOME/.cache/icedtea-web" ]; then
    rm -rf "$HOME/.cache/icedtea-web" 2>/dev/null || true
elif [ -f "$HOME/.cache/icedtea-web" ]; then
    rm -f "$HOME/.cache/icedtea-web" 2>/dev/null || true
fi

# Remove $HOME/.config/icedtea-web
echo "Removing $HOME/.config/icedtea-web..."
if [ -d "$HOME/.config/icedtea-web" ]; then
    rm -rf "$HOME/.config/icedtea-web" 2>/dev/null || true
elif [ -f "$HOME/.config/icedtea-web" ]; then
    rm -f "$HOME/.config/icedtea-web" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
